window.BQ = window.BQ || {};
BQ.BANK = [
// ======================= E/R =======================
{id:'er1',topic:'er',type:'choice',title:'Figuras de Chen',q:'En notación Chen, ¿qué figura representa una relación?',opts:[['Rombo',true,'Rombo = relación (el verbo).'],['Rectángulo',false,'Es la entidad.'],['Óvalo',false,'Es el atributo.'],['Doble rectángulo',false,'Es una entidad débil.']],truco:'Rectángulo = cosa, óvalo = dato, rombo = verbo.'},
{id:'er2',topic:'er',type:'choice',title:'Teléfonos',q:'Un cliente puede tener varios teléfonos. En Chen, ¿cómo se dibuja el atributo teléfono?',opts:[['Doble óvalo (multivalorado)',true,'Varios valores → multivalorado → doble óvalo.'],['Óvalo discontinuo',false,'Eso es un derivado (se calcula).'],['Óvalo con subrayado',false,'Subrayado = identificador.'],['Rombo',false,'El rombo es una relación.']],truco:'Doble óvalo = "doble" de valores.'},
{id:'er3',topic:'er',type:'choice',title:'La edad',q:'Se guarda fecha_nacimiento y se quiere mostrar la edad. ¿Qué tipo de atributo es la edad?',opts:[['Derivado: óvalo discontinuo y no se guarda',true,'Se calcula desde fecha_nacimiento; guardarla la desincroniza.'],['Multivalorado',false,'Una persona tiene una sola edad.'],['Compuesto',false,'No se divide en partes.'],['Identificador',false,'No identifica a nadie.']],truco:'Discontinuo = "no está del todo": se calcula.'},
{id:'er4',topic:'er',type:'choice',title:'Línea de pedido',q:'Una línea de pedido se identifica por el número de pedido + su posición (1, 2, 3…) y no tiene sentido sin el pedido. ¿Qué es Línea?',opts:[['Entidad débil con clave parcial "posición"',true,'Depende del pedido para existir y para identificarse.'],['Entidad fuerte',false,'No se identifica sola.'],['Atributo multivalorado de Pedido',false,'Tiene sus propios atributos (producto, cantidad…).'],['Una relación ternaria',false,'Solo depende de Pedido.']],truco:'Débil = "no vive sola". Todo doble: rectángulo, rombo, y participación total.'},
{id:'er5',topic:'er',type:'choice',title:'Clave parcial',q:'¿Cómo se marca la clave parcial de una entidad débil en Chen?',opts:[['Subrayado discontinuo',true,'La clave completa sale de la fuerte + la parcial.'],['Subrayado continuo',false,'Ese es el identificador de una entidad fuerte.'],['Doble óvalo',false,'Eso es multivalorado.'],['En negrita',false,'No es la convención.']],truco:'Clave parcial = subrayado "a medias" (discontinuo).'},
{id:'er6',topic:'er',type:'choice',title:'DNI y pasaporte',q:'Una persona se puede identificar por DNI o por número de pasaporte. Eliges el DNI. ¿Qué es el pasaporte?',opts:[['Clave alternativa (UNIQUE al implementar)',true,'Es candidata, pero no la principal.'],['Clave parcial',false,'Eso es en entidades débiles.'],['Atributo derivado',false,'No se calcula.'],['Nada: se borra',false,'Sigue sin poder repetirse.']],truco:'Candidatas: una principal (subrayada) y el resto alternativas con UNIQUE.'},
{id:'er7',topic:'er',type:'choice',title:'Email como PK',q:'¿Por qué no conviene usar el email como clave primaria?',opts:[['Porque puede cambiar y arrastraría todas las FK',true,'La PK debe ser estable; si cambia, hay que actualizarla en cascada.'],['Porque los emails se repiten siempre',false,'Normalmente no se repiten.'],['Porque es un número',false,'Es texto.'],['Porque MySQL no lo permite',false,'Lo permite, pero es mala idea.']],truco:'PK estable y corta. Si puede cambiar → id + UNIQUE en el email.'},
{id:'er8',topic:'er',type:'choice',title:'Proveedor, producto y almacén',q:'El precio depende a la vez del proveedor, el producto y el almacén al que se sirve. ¿Cómo se modela?',opts:[['Una relación ternaria con el atributo precio',true,'El precio es del trío; en tres binarias se perdería.'],['Tres relaciones binarias',false,'Pierdes la regla conjunta: no sabrías qué precio va con qué combinación.'],['Precio como atributo de Producto',false,'El precio cambia según proveedor y almacén.'],['Una ISA',false,'No hay especialización.']],truco:'Si el dato depende de los tres a la vez, la relación es de los tres.'},
{id:'er9',topic:'er',type:'choice',title:'Supervisa',q:'Un empleado puede supervisar a otros empleados. ¿Qué relación es?',opts:[['Reflexiva (unaria) con roles supervisor y subordinado',true,'Une la entidad consigo misma; los roles evitan la ambigüedad.'],['Ternaria',false,'Solo interviene una entidad.'],['ISA',false,'No es especialización.'],['N:M obligatoria',false,'Normalmente un empleado tiene 0 o 1 supervisor.']],truco:'Reflexiva = espejo: la entidad se mira a sí misma. Pon nombre a los roles.'},
{id:'er10',topic:'er',type:'choice',title:'Nota del alumno',q:'Estudiante cursa módulo (N:M). ¿Dónde va la nota de cada alumno en cada módulo? (Boletín 0)',opts:[['Como atributo de la relación "cursa"',true,'La nota no es ni del alumno solo ni del módulo solo: es del par.'],['En Estudiante',false,'Un estudiante tiene una nota por módulo.'],['En Módulo',false,'Cada alumno tiene la suya.'],['Como entidad Nota sin relaciones',false,'Perdería con qué alumno y módulo va.']],truco:'Si el dato es "del encuentro", va en el rombo.'},
{id:'er11',topic:'er',type:'choice',title:'¿Total o parcial?',q:'"Un cliente puede no haber hecho ningún pedido". ¿Qué participación tiene Cliente en "realiza"?',opts:[['Parcial (mínimo 0)',true,'"Puede no" → mínimo 0 → opcional.'],['Total (mínimo 1)',false,'Total sería "todo cliente tiene al menos un pedido".'],['N:M',false,'Eso es el tipo, no la participación.'],['Débil',false,'Cliente no depende de nadie.']],truco:'"Puede" → 0. "Siempre / todo / debe" → 1.'},
{id:'er12',topic:'er',type:'choice',title:'Cómo se lee el par',q:'Según la web (conceptual 4.4): Cliente (0,N) —realiza— Pedido (1,1). ¿Qué dice el (0,N) pegado a Cliente?',opts:[['Que un cliente puede estar en 0 a N pedidos',true,'El par se lee desde la entidad de ese extremo hacia la relación.'],['Que un pedido tiene de 0 a N clientes',false,'Eso lo diría un (0,N) junto a Pedido.'],['Que la relación es N:M',false,'El otro extremo es (1,1): es 1:N.'],['Que Cliente es débil',false,'No hay doble rectángulo.']],truco:'Par pegado a X = con cuántas de LA OTRA se relaciona UNA X. Escribe siempre la frase al lado.'},
{id:'er13',topic:'er',type:'choice',title:'Tipo de la relación',q:'Un autor escribe libros y un libro puede tener varios autores. ¿Qué tipo es "escribe"?',opts:[['N:M',true,'Los dos máximos son N.'],['1:N',false,'Un libro puede tener varios autores.'],['1:1',false,'Hay muchos por los dos lados.'],['Reflexiva',false,'Son dos entidades distintas.']],truco:'Pregunta el máximo en los dos sentidos: N y N → N:M.'},
{id:'er14',topic:'er',type:'choice',title:'Coche y matrícula',q:'"Un coche tiene matrícula" (Boletín 0). ¿Lo mejor en el E/R?',opts:[['Matrícula como atributo identificador de Coche',true,'Es un dato del coche que lo identifica; no tiene vida propia.'],['Entidad Matrícula con relación 1:1',false,'No tiene atributos propios: sobra.'],['Relación N:M',false,'Un coche tiene una sola matrícula.'],['Atributo multivalorado',false,'Solo hay una.']],truco:'Si no tiene datos propios, es atributo, no entidad.'},
{id:'er15',topic:'er',type:'choice',title:'ISA disyunta',q:'"Un vehículo puede ser coche o moto, pero nunca las dos cosas; y hay vehículos que no son ninguna". ¿Qué ISA es?',opts:[['Disyunta y parcial',true,'Exclusión [D] y puede no estar en ningún subtipo (línea simple).'],['Disyunta y total',false,'Total exigiría que todo vehículo sea coche o moto.'],['Solapada y parcial',false,'Solapada permitiría ser coche y moto.'],['Solapada y total',false,'Ni solape ni obligación.']],truco:'¿Las dos a la vez? → Solapada. ¿Tiene que ser alguna? → Total.'},
{id:'er16',topic:'er',type:'choice',title:'Roles a la vez',q:'"Toda persona de la universidad es alumno o empleado, y puede ser ambos (becario)". ¿Qué ISA es?',opts:[['Solapada y total',true,'Puede estar en los dos [O] y todos están en alguno (doble línea).'],['Disyunta y total',false,'Disyunta impediría ser ambos.'],['Solapada y parcial',false,'Parcial permitiría personas sin rol.'],['No es ISA',false,'Es una especialización clásica.']],truco:'Becario = alumno + empleado → solapa.'},
{id:'er17',topic:'er',type:'choice',title:'Subtipo vacío',q:'Un subtipo de la ISA no tiene ningún atributo ni regla propia. ¿Qué recomienda la web?',opts:[['Quitarlo y usar un atributo "tipo" en el supertipo',true,'Un subtipo que no aporta nada solo complica.'],['Dejarlo siempre',false,'Añade tablas sin aportar.'],['Convertirlo en entidad débil',false,'No depende de nadie.'],['Hacerlo multivalorado',false,'No es una lista.']],truco:'Subtipo sin nada propio = valor de un atributo.'},
{id:'er18',topic:'er',type:'choice',title:'Agregación',q:'Quieres decir que "ese proveedor suministrando ese producto" sirve a un almacén. ¿Qué usas?',opts:[['Agregación: encierras Proveedor–suministra–Producto y la relacionas con Almacén',true,'Relacionas la combinación, no cada entidad suelta.'],['Composición',false,'No hay todo–parte con dependencia.'],['Dos relaciones binarias con Almacén',false,'Perderías qué pareja sirve a qué almacén.'],['ISA',false,'No es especialización.']],truco:'Agregación = relacionar "la pareja".'},
{id:'er19',topic:'er',type:'choice',title:'Familias de restricciones',q:'"Un pedido cancelado no puede tener líneas". ¿Qué tipo de restricción es?',opts:[['Semántica (regla de negocio): nota en el E/R',true,'No sale de tipos, claves ni (min,max).'],['De dominio',false,'Dominio es tipo, rango y formato de un atributo.'],['De entidad',false,'Entidad es identidad y unicidad.'],['De referencia',false,'Referencia es que exista lo relacionado.']],truco:'D-E-R-S: Dominio, Entidad, Referencia, Semántica.'},
{id:'er20',topic:'er',type:'match',title:'Componentes de Chen',prompt:'Une cada elemento con su dibujo.',pairs:[['Entidad débil','Doble rectángulo','No se identifica sola.'],['Atributo multivalorado','Doble óvalo','Varios valores.'],['Atributo derivado','Óvalo discontinuo','Se calcula.'],['Relación identificadora','Doble rombo','Une la débil con su fuerte.'],['Identificador','Atributo subrayado','La clave principal.']],truco:'Todo lo "doble" va con la débil o con varios valores.'},
{id:'er21',topic:'er',type:'match',title:'ISA: ejemplos de la web',prompt:'Une cada jerarquía con su tipo.',pairs:[['Empleado → Técnico | Administrativo','Disyunta y total','Todos son uno de los dos, nunca ambos.'],['Vehículo → Coche | Moto','Disyunta y parcial','Hay camiones.'],['Persona → Alumno | Empleado','Solapada y total','Un becario es ambos; todos tienen algún rol.'],['Producto → Perecedero | Refrigerado','Solapada y parcial','Puede ser ninguno, uno o los dos.']],truco:'Pregunta 1: ¿a la vez? Pregunta 2: ¿obligatorio?'},
{id:'er22',topic:'er',type:'match',title:'Palabras del enunciado',prompt:'Une cada expresión con lo que te dice.',pairs:[['"puede no tener"','mínimo 0','Opcional.'],['"siempre" / "todo"','mínimo 1','Obligatorio.'],['"varios" / "muchos"','máximo N','Muchos a la vez.'],['"un único" / "solo uno"','máximo 1','Como mucho uno.']],truco:'Puede → 0. Siempre → 1. Varios → N. Único → 1.'},
{id:'er23',topic:'er',type:'match',title:'UML y E/R',prompt:'Une cada multiplicidad UML con su (min,max).',pairs:[['1','(1,1)','Exactamente uno.'],['0..1','(0,1)','Cero o uno.'],['0..* o *','(0,N)','Cero o muchos.'],['1..*','(1,N)','Uno o muchos.']],truco:'El asterisco es la N.'},
{id:'er24',topic:'er',type:'order',title:'Método del enunciado',q:'Ordena los pasos para sacar el E/R de un enunciado.',steps:['Subrayar los sustantivos (candidatos a entidad)','Subrayar los verbos (relaciones)','Para cada relación, preguntar mínimos y máximos en los dos sentidos','Comprobar con contraejemplos'],why:'Primero las cosas, luego cómo se unen, luego cuántos, y al final intentas romperlo.',truco:'Sustantivos, verbos, números, contraejemplo.'},
{id:'er25',topic:'er',type:'order',title:'Ruta del diseño',q:'Ordena las fases del diseño de una base de datos.',steps:['Requisitos y vocabulario','Modelo conceptual (E/R)','Diseño lógico (tablas)','Normalización','Implementación (DDL)','Carga y manipulación (DML)'],why:'Del significado (E/R) a las tablas, se limpian (normalización) y se crean y llenan en SQL.',truco:'Entender → dibujar → tablas → limpiar → crear → llenar.'},
{id:'er26',topic:'er',type:'short',title:'Escribe: participación',q:'Explica qué significa el mínimo de un (min,max) y qué valores puede tener.',groups:[['0'],['1'],['opcional','parcial'],['obligatori','total']],model:'El mínimo dice si la participación es obligatoria: 0 = parcial u opcional (puede no estar relacionada) y 1 = total u obligatoria (siempre está relacionada).',why:'Hay que dar los dos valores y qué significa cada uno.',truco:'Mínimo = ¿obligatorio? Máximo = ¿cuántos a la vez?'},
{id:'er27',topic:'er',type:'short',title:'Escribe: entidad débil',q:'Di qué es una entidad débil, cómo se identifica y pon un ejemplo.',groups:[['no tiene identificador','no se identifica sola','no puede existir','depende','sin su'],['parcial'],['linea','ejemplar','pedido','habitacion','factura','estanteria']],model:'Una entidad débil no puede identificarse ni existir sin su entidad fuerte: se identifica con la clave de la fuerte + una clave parcial. Ejemplo: Línea de pedido (id_pedido + posición).',why:'Faltaba la idea de dependencia, la clave parcial o el ejemplo.',truco:'Débil = clave de la fuerte + clave parcial.'},
{id:'er28',topic:'er',type:'short',title:'Escribe: ternaria',q:'¿Por qué una relación ternaria no es lo mismo que tres binarias?',groups:[['pierde','perder','conjunt','a la vez','los tres','combinaci','junt']],model:'Porque la ternaria guarda un hecho que depende de los tres a la vez (el precio de ese proveedor, para ese producto y ese almacén). Con tres binarias se pierde esa regla conjunta y no sabes qué combinación va con qué.',why:'La idea clave es que se pierde la información conjunta.',truco:'Tres binarias = tres parejas sueltas. La ternaria es el trío.'},
{id:'er29',topic:'er',type:'multi',title:'Señales de entidad',q:'Marca las razones por las que algo debería ser una ENTIDAD y no un atributo.',opts:[['Tiene varias propiedades propias',true,'Una sucursal con dirección, teléfono y horario.'],['Se relaciona con otras entidades',true,'Necesita sus propias relaciones.'],['Hay que identificarlo por separado',true,'Tiene identidad propia.'],['Es un único valor sin más datos',false,'Eso es un atributo.'],['Se calcula a partir de otros',false,'Eso es un derivado.']],truco:'Vida propia = entidad.'},

// ======================= PASO A TABLAS =======================
{id:'tb1',topic:'tab',type:'choice',title:'¿Dónde va la FK?',q:'Cliente —realiza— Pedido es 1:N (un cliente, muchos pedidos). ¿Dónde va la clave ajena?',opts:[['En PEDIDO: cliente_id → CLIENTE(id)',true,'La FK va en el lado N: cada pedido apunta a su único cliente.'],['En CLIENTE: pedido_id → PEDIDO(id)',false,'Un cliente tiene muchos pedidos: no caben en una columna.'],['En una tabla intermedia',false,'Una 1:N nunca necesita tabla intermedia.'],['En las dos tablas',false,'Duplica y desincroniza.']],truco:'La FK viaja a los "muchos".'},
{id:'tb2',topic:'tab',type:'choice',title:'N:M',q:'Pedido incluye Producto (N:M) con el atributo unidades. ¿Cómo queda?',opts:[['Tabla LINEA con CP(pedido_id, producto_id), las dos C.Aj y unidades',true,'Tabla intermedia con CP compuesta por las dos FKs y el atributo de la relación.'],['FK producto_id en PEDIDO',false,'Un pedido tiene muchos productos.'],['FK pedido_id en PRODUCTO',false,'Un producto está en muchos pedidos.'],['Tabla LINEA con CP(pedido_id)',false,'Solo cabría un producto por pedido.']],truco:'N:M = puente con dos FKs que juntas son la CP.'},
{id:'tb3',topic:'tab',type:'choice',title:'¿VNN o NULL?',q:'"Todo pedido pertenece a un cliente". En PEDIDO, ¿cómo es cliente_id?',opts:[['C.Aj + VNN',true,'Un pedido no puede existir sin cliente → no admite NULL.'],['C.Aj que admite NULL',false,'Permitiría pedidos sin cliente.'],['C.Alt',false,'Muchos pedidos tienen el mismo cliente: no es único.'],['CP',false,'La CP del pedido es su propio id.']],truco:'¿Puede existir un PEDIDO sin CLIENTE? No → VNN.'},
{id:'tb4',topic:'tab',type:'choice',title:'Jefe opcional',q:'EMPLEADO = dni + nombre + jefe_dni. Un empleado puede no tener jefe. ¿Qué escribes?',opts:[['C.Aj(jefe_dni) → EMPLEADO(dni), sin VNN',true,'Reflexiva: FK a la propia tabla, y admite NULL porque es opcional.'],['C.Aj(jefe_dni) → EMPLEADO(dni) + VNN',false,'Obligaría a que todos tengan jefe (¿y el director?).'],['Tabla JEFE aparte',false,'Una reflexiva 1:N se resuelve con una FK en la misma tabla.'],['C.Alt(jefe_dni)',false,'Un jefe tiene varios subordinados: se repite.']],truco:'Reflexiva = FK que apunta a su propia tabla.'},
{id:'tb5',topic:'tab',type:'choice',title:'1:1',q:'Persona tiene 0 o 1 pasaporte y cada pasaporte es de una persona. FK persona_id en PASAPORTE. ¿Qué más hace falta?',opts:[['C.Alt(persona_id) (UNIQUE) y VNN(persona_id)',true,'UNIQUE para que una persona no tenga dos pasaportes; VNN porque todo pasaporte es de alguien.'],['Nada más',false,'Sin UNIQUE sería un 1:N.'],['Tabla intermedia',false,'En 1:1 se evita.'],['CP(persona_id, id)',false,'No es una N:M.']],truco:'1:1 = FK + UNIQUE.'},
{id:'tb6',topic:'tab',type:'choice',title:'Teléfonos',q:'Un cliente tiene varios teléfonos (multivalorado). ¿Cómo se pasa a tablas?',opts:[['TEL_CLI = cliente_id + telefono · CP(cliente_id, telefono) · C.Aj(cliente_id) → CLIENTE(id)',true,'Tabla propia con CP compuesta (base + valor).'],['Columna telefonos con los números separados por comas',false,'Rompe la 1FN: no puedes buscar ni validar uno a uno.'],['telefono1, telefono2, telefono3 en CLIENTE',false,'Grupo repetitivo: ¿y si tiene cuatro?'],['C.Alt(telefono) en CLIENTE',false,'Sigue siendo una sola columna.']],truco:'Lista = tabla aparte.'},
{id:'tb7',topic:'tab',type:'choice',title:'Débil',q:'LINEA es débil de PEDIDO con clave parcial pos. ¿Cuál es su CP?',opts:[['CP(pedido_id, pos)',true,'PK de la fuerte + clave parcial.'],['CP(pos)',false,'Todas las primeras líneas tendrían pos 1.'],['CP(pedido_id)',false,'Un pedido tiene varias líneas.'],['CP(id) inventado',false,'Se puede, pero no es el mapeo de la débil.']],truco:'Débil = clave del "padre" + su número.'},
{id:'tb8',topic:'tab',type:'choice',title:'ISA en tablas',q:'Persona → Alumno | Profesor. ¿Cuál es la CP de la tabla ALUMNO?',opts:[['id, que además es C.Aj → PERSONA(id)',true,'El subtipo hereda la clave: es a la vez CP y FK.'],['Un id_alumno nuevo sin relación',false,'Perderías que es la misma persona.'],['(id, curso)',false,'Curso no identifica.'],['No tiene CP',false,'Toda tabla tiene CP.']],truco:'ISA: la CP del hijo es la FK al padre.'},
{id:'tb9',topic:'tab',type:'choice',title:'C.Alt y NULL',q:'Pones C.Alt(nif) en CLIENTE. ¿Puede haber dos clientes con nif NULL?',opts:[['Sí: UNIQUE admite varios NULL. Si es obligatorio, añade VNN(nif)',true,'NULL no es igual a NULL, así que no choca.'],['No, UNIQUE no admite NULL',false,'Sí los admite (varios).'],['Solo uno',false,'Admite varios.'],['Depende del AUTO_INCREMENT',false,'No tiene que ver.']],truco:'"Único y obligatorio" = C.Alt + VNN.'},
{id:'tb10',topic:'tab',type:'choice',title:'¿A qué apunta una FK?',q:'C.Aj(x) → T(k). ¿Qué tiene que ser k?',opts:[['La PK o una clave alternativa (UNIQUE) de T',true,'Si k no es única, no se sabría a qué fila apunta.'],['Cualquier columna de T',false,'Tiene que ser única.'],['Una columna NOT NULL',false,'No basta: puede repetirse.'],['Una FK de T',false,'No: una clave de T.']],truco:'Una FK apunta a algo que identifica: PK o UNIQUE.'},
{id:'tb11',topic:'tab',type:'choice',title:'SET NULL',q:'¿Cuándo se puede usar ON DELETE SET NULL en una FK?',opts:[['Solo si la FK admite NULL (participación opcional)',true,'No puedes poner NULL en una columna NOT NULL.'],['Siempre',false,'Con VNN falla.'],['Solo en tablas intermedias',false,'Ahí suele ir CASCADE.'],['Solo si la FK es PK',false,'La PK no admite NULL.']],truco:'SET NULL + VNN = imposible.'},
{id:'tb12',topic:'tab',type:'choice',title:'Política de la débil',q:'¿Qué política de borrado sugiere la web para LINEA (débil) respecto a PEDIDO?',opts:[['ON DELETE CASCADE',true,'Si borras el pedido, sus líneas no tienen sentido.'],['ON DELETE SET NULL',false,'La FK de la débil es VNN (y parte de la CP).'],['Ninguna',false,'Hay que decidirla.'],['ON DELETE RESTRICT siempre',false,'Para la débil se sugiere CASCADE.']],truco:'La parte muere con el todo → CASCADE.'},
{id:'tb13',topic:'tab',type:'choice',title:'Cobertura',q:'"Todo producto aparece en algún suministro". ¿Cómo se expresa en el marco?',opts:[['ASERCIÓN: PRODUCTO[id] ⊆ SUMINISTRO[producto_id]',true,'La participación total del lado "uno" no sale con FK: es una aserción de cobertura.'],['VNN(id) en PRODUCTO',false,'La CP ya es no nula; no obliga a aparecer en otra tabla.'],['C.Aj en PRODUCTO',false,'Producto no apunta a suministro.'],['C.Alt(producto_id)',false,'Un producto puede aparecer varias veces.']],truco:'⊆ = "todos están dentro de".'},
{id:'tb14',topic:'tab',type:'choice',title:'CP mínima',q:'En LINEA(pedido_id, producto_id, unidades) con CP(pedido_id, producto_id, unidades), ¿qué falla?',opts:[['No es mínima: unidades sobra',true,'Con (pedido_id, producto_id) ya se identifica; añadir unidades permitiría repetir el par.'],['No es única',false,'Única es, pero no mínima.'],['Admite NULL',false,'Las columnas de la CP no admiten NULL.'],['Nada',false,'Sobra una columna.']],truco:'U-M-N: si sobra una columna, no es mínima.'},
{id:'tb15',topic:'tab',type:'match',title:'Marco → SQL',prompt:'Une cada marca del marco con su SQL.',pairs:[['CP(a, b)','PRIMARY KEY (a, b)','Clave primaria.'],['C.Alt(x)','UNIQUE (x)','Clave alternativa.'],['C.Aj(f) → T(k)','FOREIGN KEY (f) REFERENCES T(k)','Clave ajena.'],['VNN(c)','c … NOT NULL','Valor no nulo.'],['ASERCIÓN','Trigger o lógica de la aplicación','MySQL no tiene aserciones.']],truco:'CP, Alt, Aj, VNN: quién soy, otro DNI, a quién apunto, lo que no falta.'},
{id:'tb16',topic:'tab',type:'match',title:'Patrón → tabla',prompt:'Une cada patrón del E/R con cómo se pasa a tablas.',pairs:[['1:N','FK en el lado N','Sin tabla nueva.'],['N:M','Tabla intermedia con CP compuesta','Con los atributos de la relación.'],['1:1','FK en un lado + UNIQUE','Para que no se repita.'],['Multivalorado','Tabla propia CP(base, valor)','Un valor por fila.'],['Reflexiva 1:N','FK a la propia tabla','jefe_id → EMPLEADO(id).']],truco:'Solo N:M, ternaria y multivalorado crean tabla nueva.'},
{id:'tb17',topic:'tab',type:'match',title:'Políticas de FK',prompt:'Une cada política con lo que hace.',pairs:[['RESTRICT / NO ACTION','Impide borrar si hay hijos','Protege de huérfanos.'],['CASCADE','Borra también los hijos','Típico en intermedias y débiles.'],['SET NULL','Deja la FK de los hijos a NULL','Solo si la FK admite NULL.'],['SET DEFAULT','No existe en MySQL','Hay que usar otra.']],truco:'Restrict = "no te dejo". Cascade = "me llevo a todos". Set null = "os quedáis sin padre".'},
{id:'tb18',topic:'tab',type:'order',title:'Guía de 5 pasos',q:'Ordena el análisis de claves de una tabla.',steps:['¿Qué identifica cada fila (única, mínima, no nula)? → CP','¿Hay identificadores naturales que no se repiten? → C.Alt','¿Qué columnas apuntan a otra tabla? → C.Aj','¿Qué columnas son obligatorias? → VNN','¿La CP es compuesta?'],why:'Primero la identidad, luego las otras unicidades, las referencias, la obligatoriedad y la revisión de la CP.',truco:'CP, Alt, Aj, VNN, ¿compuesta?'},
{id:'tb19',topic:'tab',type:'short',title:'Escribe: regla del 1:N',q:'Explica dónde va la clave ajena en una relación 1:N y cuándo lleva VNN.',groups:[[' n','muchos','lado n'],['vnn','not null','no nul'],['obligatori','minimo 1','min 1','min=1','sin','siempre','total']],model:'La FK va en la tabla del lado N (los "muchos") apuntando a la PK del lado 1. Lleva VNN cuando la participación es obligatoria (cada fila del lado N tiene siempre su padre, mínimo 1).',why:'Faltaba el lado o la condición del VNN.',truco:'FK a los muchos; VNN si "no puede existir sin".'},
{id:'tb20',topic:'tab',type:'short',title:'Escribe: CP',q:'¿Qué tres condiciones cumple una clave primaria?',groups:[['unica','unico'],['minima','minimo'],['no nula','no nul','not null','vnn']],model:'Única, mínima y no nula.',why:'Son tres: única, mínima y no nula.',truco:'U-M-N.'},
{id:'tb21',topic:'tab',type:'short',title:'Escribe: CP de la N:M',q:'LINEA_UTILIZA = reparacion_id + pieza_codigo + unidades. Escribe su CP y justifica por qué no basta con reparacion_id.',groups:[['reparacion_id'],['pieza_codigo'],['solo una','una pieza','una sola','varias','repet']],model:'CP(reparacion_id, pieza_codigo). Con solo reparacion_id cada reparación podría usar una única pieza, porque no se podría repetir el id; el par sí identifica "esta reparación usa esta pieza".',why:'Había que dar las dos columnas y la consecuencia de quitar una.',truco:'Si quitas una columna de la CP compuesta, pregúntate qué deja de poder repetirse.'},
{id:'tb22',topic:'tab',type:'multi',title:'Errores al pasar a tablas',q:'Marca los que son ERRORES.',opts:[['Crear tabla intermedia para un 1:N',true,'Sobra: basta la FK en el lado N.'],['Poner la FK en el lado 1',true,'No cabe: el lado 1 tiene muchos hijos.'],['VNN en una FK cuya participación es opcional',true,'Impediría filas sin padre que el enunciado permite.'],['C.Alt en la matrícula de un coche con CP id',false,'Correcto: protege el identificador natural.'],['Atributo de la N:M en la tabla intermedia',false,'Correcto: es su sitio.']],truco:'Repasa: lado de la FK, tablas que sobran, VNN según el enunciado.'},

// ======================= DDL =======================
{id:'dd1',topic:'ddl',type:'choice',title:'Dinero',q:'¿Qué tipo usarías para el precio de un producto?',opts:[['DECIMAL(10,2)',true,'Exacto: para dinero.'],['FLOAT',false,'Aproximado: errores de redondeo.'],['VARCHAR(10)',false,'No podrías sumar ni comparar bien.'],['INT',false,'Perderías los céntimos.']],truco:'DECIMAL = Dinero.'},
{id:'dd2',topic:'ddl',type:'choice',title:'DNI',q:'¿Qué tipo es más adecuado para un DNI español (8 números + letra)?',opts:[['CHAR(9)',true,'Longitud fija de 9 caracteres.'],['INT',false,'Perderías la letra.'],['VARCHAR(255)',false,'Tamaño "porque sí": antipatrón.'],['DECIMAL(9,0)',false,'No admite la letra.']],truco:'Largo fijo = CHAR.'},
{id:'dd3',topic:'ddl',type:'choice',title:'Dos PRIMARY KEY',q:'¿Qué pasa con este CREATE?',code:'CREATE TABLE socio (\n  id INT AUTO_INCREMENT PRIMARY KEY,\n  nombre VARCHAR(60) NOT NULL,\n  PRIMARY KEY (id)\n);',opts:[['Error: la clave primaria está declarada dos veces',true,'Una tabla tiene una sola PK ("Multiple primary key defined").'],['Está bien: se refuerza',false,'MySQL da error.'],['Crea una PK compuesta',false,'Para compuesta: PRIMARY KEY (a, b) una vez.'],['Solo falla por el AUTO_INCREMENT',false,'El problema es la PK duplicada.']],truco:'Una tabla, una PK: en la columna o al final, nunca en los dos sitios.'},
{id:'dd4',topic:'ddl',type:'choice',title:'PK compuesta mal escrita',q:'¿Qué está mal?',code:'CREATE TABLE matricula (\n  alumno_id INT PRIMARY KEY,\n  curso_id  INT PRIMARY KEY,\n  fecha     DATE NOT NULL\n);',opts:[['La PK compuesta se declara una vez: PRIMARY KEY (alumno_id, curso_id)',true,'Escribir PRIMARY KEY en cada columna son dos PK → error.'],['Falta AUTO_INCREMENT',false,'No hace falta en una intermedia.'],['fecha no puede ser NOT NULL',false,'Puede.'],['Está bien',false,'Da error.']],truco:'Compuesta = un PRIMARY KEY con paréntesis.'},
{id:'dd5',topic:'ddl',type:'choice',title:'Orden de creación',q:'Se ejecuta el script en este orden. ¿Qué pasa?',code:'CREATE TABLE pedido (\n  id INT PRIMARY KEY,\n  cliente_id INT NOT NULL,\n  FOREIGN KEY (cliente_id) REFERENCES cliente(id)\n);\nCREATE TABLE cliente (\n  id INT PRIMARY KEY\n);',opts:[['Error en pedido: cliente aún no existe',true,'La tabla referenciada tiene que existir antes (o añadir la FK con ALTER al final).'],['Funciona: MySQL lo ordena solo',false,'No reordena el script.'],['Error en cliente',false,'cliente está bien.'],['Funciona pero sin FK',false,'Falla el CREATE.']],truco:'Primero los padres, después los hijos.'},
{id:'dd6',topic:'ddl',type:'choice',title:'Tipos de la FK',q:'¿Qué falla?',code:'CREATE TABLE equipo (\n  nomeq VARCHAR(25) PRIMARY KEY\n);\nCREATE TABLE ciclista (\n  dorsal SMALLINT PRIMARY KEY,\n  nomeq  INT NOT NULL,\n  FOREIGN KEY (nomeq) REFERENCES equipo(nomeq)\n);',opts:[['El tipo de la FK (INT) no coincide con el de la PK (VARCHAR(25))',true,'La FK y lo referenciado deben ser del mismo tipo.'],['Falta ON DELETE',false,'Es opcional (por defecto RESTRICT).'],['nomeq no puede ser NOT NULL',false,'Todo ciclista tiene equipo.'],['dorsal debe ser INT',false,'SMALLINT vale.']],truco:'FK: existe, es clave y es del mismo tipo.'},
{id:'dd7',topic:'ddl',type:'choice',title:'FK a columna no clave',q:'¿Qué falla en la última línea?',code:'CREATE TABLE taller (\n  id_taller INT PRIMARY KEY,\n  equipo    VARCHAR(100) NOT NULL\n);\nCREATE TABLE inscripcion (\n  id_taller INT NOT NULL,\n  FOREIGN KEY (id_taller) REFERENCES taller(equipo)\n);',opts:[['Referencia taller(equipo), que no es PK ni UNIQUE (y es de otro tipo)',true,'Debe referenciar taller(id_taller).'],['Falta NOT NULL',false,'Lo tiene.'],['inscripcion necesita AUTO_INCREMENT',false,'No es el error.'],['No falla',false,'MySQL lo rechaza.']],truco:'Una FK apunta a algo que identifica.'},
{id:'dd8',topic:'ddl',type:'choice',title:'SET NULL imposible',q:'¿Qué falla?',code:'CREATE TABLE pedido (\n  id INT PRIMARY KEY,\n  comercial_id INT NOT NULL,\n  FOREIGN KEY (comercial_id) REFERENCES comercial(id)\n    ON DELETE SET NULL\n);',opts:[['SET NULL necesita que comercial_id admita NULL',true,'O se quita NOT NULL (si es opcional) o se usa RESTRICT.'],['ON DELETE no existe',false,'Existe.'],['Falta UNIQUE',false,'Un comercial tiene muchos pedidos.'],['Nada',false,'Es contradictorio.']],truco:'No puedes poner a NULL lo que no admite NULL.'},
{id:'dd9',topic:'ddl',type:'choice',title:'Identificador natural',q:'Enunciado: "la matrícula no puede repetirse". ¿Qué le falta a esta columna?',code:'matricula CHAR(7) NOT NULL,',opts:[['UNIQUE',true,'NOT NULL no evita duplicados; UNIQUE sí (C.Alt).'],['PRIMARY KEY obligatoriamente',false,'Puede ser C.Alt si la PK es un id.'],['DEFAULT',false,'No tiene que ver.'],['Nada',false,'Podrían repetirse matrículas.']],truco:'"No se repite" → UNIQUE. "Obligatorio" → NOT NULL. Son cosas distintas.'},
{id:'dd10',topic:'ddl',type:'choice',title:'Opcional con NOT NULL',q:'Enunciado: "la fecha de salida puede no existir (el coche sigue en el taller)". ¿Qué está mal?',code:'fecha_salida DATE NOT NULL,',opts:[['Sobra NOT NULL: debe admitir NULL',true,'"Puede no existir" = opcional.'],['Debería ser VARCHAR',false,'Una fecha es DATE.'],['Falta UNIQUE',false,'Muchas reparaciones salen el mismo día.'],['Nada',false,'No dejaría registrar coches sin salir.']],truco:'El NOT NULL también puede sobrar.'},
{id:'dd11',topic:'ddl',type:'choice',title:'Sin NOT NULL',q:'Una columna se escribe sin NOT NULL. ¿Qué significa?',opts:[['Que admite NULL (es opcional)',true,'El silencio también decide.'],['Que es obligatoria por defecto',false,'Al revés.'],['Que es única',false,'Eso sería UNIQUE.'],['Que da error',false,'Es válido.']],truco:'Si no escribes NOT NULL, has dicho "opcional".'},
{id:'dd12',topic:'ddl',type:'choice',title:'CHECK',q:'¿Desde qué versión de MySQL se aplican de verdad los CHECK?',opts:[['8.0.16',true,'Antes se aceptaban pero se ignoraban.'],['5.0',false,'Se ignoraban.'],['Siempre se aplicaron',false,'No.'],['Nunca',false,'Desde 8.0.16 sí.']],truco:'CHECK de verdad: MySQL 8.0.16+.'},
{id:'dd13',topic:'ddl',type:'choice',title:'Motor',q:'¿Qué motor de MySQL hace falta para tener claves ajenas?',opts:[['InnoDB',true,'Es el que tiene FK y transacciones.'],['MyISAM',false,'No tiene FK.'],['MEMORY',false,'No tiene FK.'],['Cualquiera',false,'Solo InnoDB.']],truco:'Inno = Integridad.'},
{id:'dd14',topic:'ddl',type:'choice',title:'MODIFY o CHANGE',q:'Quieres cambiar el tipo de telefono a VARCHAR(25) sin cambiarle el nombre.',opts:[['ALTER TABLE clientes MODIFY telefono VARCHAR(25);',true,'MODIFY cambia el tipo con el mismo nombre.'],['ALTER TABLE clientes RENAME telefono VARCHAR(25);',false,'RENAME COLUMN cambia el nombre.'],['UPDATE clientes SET telefono = VARCHAR(25);',false,'UPDATE cambia datos, no estructura.'],['DROP TABLE clientes;',false,'Borras la tabla.']],truco:'MODIFY = mismo nombre. CHANGE = nombre nuevo.'},
{id:'dd15',topic:'ddl',type:'choice',title:'Borrar una FK',q:'¿Qué necesitas para ALTER TABLE pedidos DROP FOREIGN KEY …?',opts:[['El nombre de la restricción (SHOW CREATE TABLE)',true,'Por eso conviene CONSTRAINT nombre.'],['El nombre de la columna',false,'Se borra por el nombre de la restricción.'],['Borrar antes la tabla padre',false,'No hace falta.'],['Nada',false,'Necesitas el nombre.']],truco:'Ponle nombre a tus restricciones: CONSTRAINT fk_pedido_cliente.'},
{id:'dd16',topic:'ddl',type:'choice',title:'UNIQUE y NULL',q:'Columna a INT UNIQUE NULL. ¿Se pueden insertar dos filas con a = NULL?',opts:[['Sí',true,'UNIQUE admite varios NULL porque NULL no es igual a NULL.'],['No',false,'Sí se puede.'],['Solo si hay PK',false,'No depende.'],['Da error al crear',false,'Es válido.']],truco:'Para "único y obligatorio": NOT NULL UNIQUE.'},
{id:'dd17',topic:'ddl',type:'match',title:'Tipos de datos',prompt:'Une cada dato con su tipo.',pairs:[['Precio','DECIMAL(10,2)','Dinero exacto.'],['DNI','CHAR(9)','Largo fijo.'],['Nombre','VARCHAR(80)','Largo variable.'],['Fecha de nacimiento','DATE','Fecha sin hora.'],['Fecha y hora de una consulta','DATETIME','Con hora.'],['Descripción larga','TEXT','Texto largo.']],truco:'DECIMAL dinero, CHAR fijo, VARCHAR variable, DATE fecha.'},
{id:'dd18',topic:'ddl',type:'match',title:'ALTER TABLE',prompt:'Une cada orden con lo que hace.',pairs:[['ADD COLUMN','Añade una columna','Nueva.'],['MODIFY','Cambia tipo o NULL','Mismo nombre.'],['CHANGE','Cambia nombre y tipo','Renombra y redefine.'],['DROP FOREIGN KEY','Quita una clave ajena','Por su nombre.'],['RENAME COLUMN','Solo cambia el nombre','MySQL 8.0+.']],truco:'MODIFY = Mismo nombre.'},
{id:'dd19',topic:'ddl',type:'order',title:'Orden de creación',q:'Script de la tienda. ¿En qué orden se crean las tablas para que no falle ninguna FK?',steps:['cliente','producto','pedido (FK a cliente)','linea (FK a pedido y a producto)'],why:'Cada tabla se crea después de aquellas a las que apunta. cliente y producto no apuntan a nadie.',truco:'Primero los que no apuntan a nadie; las intermedias, al final.'},
{id:'dd20',topic:'ddl',type:'short',title:'Escribe: ¿por qué está mal?',q:'Enunciado: "cada reparación la dirige exactamente un mecánico". ¿Por qué está mal esta línea?',code:'mecanico_id INT,',groups:[['not null','vnn','nulo','null'],['obligatori','exactamente','siempre','minimo 1','min 1','un mecanico']],model:'Porque "exactamente un mecánico" significa que la participación es obligatoria (mínimo 1): la FK mecanico_id debe ser NOT NULL (VNN). Sin NOT NULL se admiten reparaciones sin mecánico.',why:'Hay que decir qué falta (NOT NULL) y por qué (es obligatorio según el enunciado).',truco:'Qué está mal + qué regla del enunciado lo exige.'},
{id:'dd21',topic:'ddl',type:'short',title:'Escribe: ¿por qué está mal?',q:'Tabla intermedia de una N:M entre ALUMNO y CURSO. ¿Por qué está mal?',code:'PRIMARY KEY (alumno_id),',groups:[['compuesta','curso_id','las dos','ambas'],['solo un','un solo','una sola','varios','repet']],model:'La CP de la tabla intermedia debe ser compuesta: PRIMARY KEY (alumno_id, curso_id). Con solo alumno_id cada alumno solo podría matricularse en un curso, porque no se podría repetir.',why:'Hay que decir la CP correcta y la consecuencia.',truco:'Error + consecuencia real ("solo podría…").'},
{id:'dd22',topic:'ddl',type:'short',title:'Escribe: ¿por qué está mal?',q:'Enunciado: "el email del usuario no puede repetirse". ¿Por qué está mal?',code:'email VARCHAR(120) NOT NULL,',groups:[['unique','c.alt','alternativa'],['repet','duplic','dos usuarios','mismo email']],model:'Falta UNIQUE (C.Alt): NOT NULL solo obliga a que haya email, pero dos usuarios podrían tener el mismo y el enunciado dice que no puede repetirse.',why:'NOT NULL y UNIQUE son cosas distintas.',truco:'Obligatorio ≠ único.'},
{id:'dd23',topic:'ddl',type:'multi',title:'Revisión de un CREATE',q:'Marca lo que tienes que revisar en cada CREATE TABLE del examen.',opts:[['Que tenga PK y que sea la correcta',true,'Error 1 y 8 de la lista.'],['Que cada FK apunte a la tabla y columna correctas y del mismo tipo',true,'Errores 2 y 6.'],['Que NOT NULL esté donde el enunciado obliga y no donde es opcional',true,'Error 4.'],['Que los identificadores naturales tengan UNIQUE',true,'Error 5.'],['Que las tablas estén en orden alfabético',false,'El orden que importa es el de las FK.']],truco:'¿PK? ¿FKs? ¿NOT NULL? ¿UNIQUE? ¿tipos? ¿orden?'},

// ======================= DML =======================
{id:'dm1',topic:'dml',type:'choice',title:'= NULL',q:'¿Qué devuelve esta consulta?',code:'SELECT * FROM alumno WHERE telefono = NULL;',opts:[['Ninguna fila: hay que usar IS NULL',true,'= NULL nunca es verdadero.'],['Los alumnos sin teléfono',false,'Eso sería IS NULL.'],['Todos los alumnos',false,'No.'],['Error de sintaxis',false,'Es válida, pero no hace lo que quieres.']],truco:'Con NULL, siempre IS.'},
{id:'dm2',topic:'dml',type:'choice',title:'WHERE o HAVING',q:'"Equipos con más de 5 ciclistas" (Boletín 1, ej. 15). ¿Qué consulta es?',opts:[['SELECT nomeq, COUNT(*) FROM ciclista GROUP BY nomeq HAVING COUNT(*) > 5;',true,'El filtro es sobre el grupo → HAVING.'],['SELECT nomeq, COUNT(*) FROM ciclista WHERE COUNT(*) > 5 GROUP BY nomeq;',false,'WHERE no admite agregados.'],['SELECT nomeq FROM ciclista WHERE dorsal > 5;',false,'Eso filtra dorsales.'],['SELECT COUNT(*) FROM ciclista HAVING nomeq > 5;',false,'Sin GROUP BY y con una condición sin sentido.']],truco:'Filtro sobre COUNT/SUM/AVG → HAVING.'},
{id:'dm3',topic:'dml',type:'choice',title:'Columna fuera del GROUP BY',q:'¿Qué falla?',code:'SELECT nomeq, nombre, COUNT(*)\nFROM ciclista\nGROUP BY nomeq;',opts:[['nombre no está en el GROUP BY ni es agregado',true,'En cada equipo hay muchos nombres: ¿cuál mostraría?'],['Falta HAVING',false,'No es obligatorio.'],['COUNT(*) no se puede usar',false,'Sí se puede.'],['Nada',false,'En modo estricto da error.']],truco:'Toda columna del SELECT: en el GROUP BY o dentro de un agregado.'},
{id:'dm4',topic:'dml',type:'choice',title:'COUNT(columna)',q:'Hay 10 alumnos y 3 no tienen teléfono (NULL). ¿Qué da SELECT COUNT(telefono) FROM alumno;?',opts:[['7',true,'COUNT(columna) no cuenta los NULL.'],['10',false,'Eso es COUNT(*).'],['3',false,'Esos son los NULL.'],['NULL',false,'COUNT nunca devuelve NULL.']],truco:'COUNT(*) = filas; COUNT(col) = filas con dato.'},
{id:'dm5',topic:'dml',type:'choice',title:'LIKE',q:'Alumnos cuyo nombre tiene exactamente 4 letras (Boletín extra, ej. 20).',opts:[["WHERE nombre LIKE '____'",true,'Cuatro guiones bajos = exactamente 4 caracteres.'],["WHERE nombre LIKE '%4%'",false,'Busca un 4 dentro del nombre.'],["WHERE nombre = 4",false,'Compara con el número 4.'],["WHERE nombre LIKE '%%%%'",false,'% es "cualquier cosa": vale todo.']],truco:'_ = exactamente uno. También: CHAR_LENGTH(nombre) = 4.'},
{id:'dm6',topic:'dml',type:'choice',title:'UPDATE sin WHERE',q:'¿Qué hace?',code:"UPDATE reparacion SET fecha_salida = '2026-11-11';",opts:[['Pone esa fecha de salida a TODAS las reparaciones',true,'Sin WHERE afecta a todas las filas.'],['Solo a la última',false,'No hay orden implícito.'],['Da error siempre',false,'Solo con SQL_SAFE_UPDATES activado.'],['Solo a las que tenían NULL',false,'Para eso: WHERE fecha_salida IS NULL.']],truco:'UPDATE/DELETE sin WHERE = toda la tabla.'},
{id:'dm7',topic:'dml',type:'choice',title:'INSERT con FK',q:'En VEHICULO solo existen los id 10, 11 y 12. ¿Qué pasa?',code:"INSERT INTO reparacion (numero_orden, fecha_entrada, vehiculo_id)\nVALUES ('R-005', '2026-11-10', 99);",opts:[['Error de integridad referencial: el vehículo 99 no existe',true,'El valor de la FK debe existir en la tabla padre.'],['Se inserta con vehiculo_id NULL',false,'MySQL no cambia el valor.'],['Se crea el vehículo 99',false,'No se crea solo.'],['Funciona',false,'La FK lo impide.']],truco:'¿Existe aquello a lo que apunto?'},
{id:'dm8',topic:'dml',type:'choice',title:'PK repetida',q:'En REPARACION ya hay filas con id 1, 2 y 3. ¿Qué pasa?',code:"INSERT INTO reparacion (id, numero_orden, fecha_entrada, vehiculo_id, mecanico_id)\nVALUES (2, 'R-004', '2026-11-10', 10, 5);",opts:[['Error: Duplicate entry, la PK 2 ya existe',true,'La PK no admite duplicados.'],['Sobrescribe la fila 2',false,'Eso sería REPLACE o ON DUPLICATE KEY UPDATE.'],['Le da el id 4',false,'Solo si no indicas el id.'],['Funciona',false,'La PK lo impide.']],truco:'¿Ya existía lo que meto?'},
{id:'dm9',topic:'dml',type:'choice',title:'Borrar un padre',q:'Borras el cliente 7, que tiene pedidos. La FK de pedido es ON DELETE RESTRICT. ¿Qué pasa?',opts:[['El DELETE falla: hay filas que dependen de él',true,'RESTRICT protege de huérfanos.'],['Se borran también sus pedidos',false,'Eso sería CASCADE.'],['Los pedidos quedan con cliente_id NULL',false,'Eso sería SET NULL.'],['Se borra sin problema',false,'La FK lo impide.']],truco:'¿Alguien depende de lo que borro?'},
{id:'dm10',topic:'dml',type:'choice',title:'Edad',q:'Edad exacta de cada alumno a partir de fecha_nacimiento:',opts:[['TIMESTAMPDIFF(YEAR, fecha_nacimiento, CURDATE())',true,'Cuenta años cumplidos.'],['YEAR(CURDATE()) - YEAR(fecha_nacimiento)',false,'Aproximada: falla si aún no ha cumplido este año.'],['DATEDIFF(fecha_nacimiento)',false,'DATEDIFF necesita dos fechas y da días.'],['NOW() - fecha_nacimiento',false,'No da años.']],truco:'Edad = TIMESTAMPDIFF(YEAR, nacimiento, hoy).'},
{id:'dm11',topic:'dml',type:'choice',title:'Los 5 primeros',q:'Obtener los 5 primeros alumnos de la tabla (Boletín extra, ej. 8).',opts:[['SELECT * FROM alumno LIMIT 5;',true,'LIMIT limita el número de filas.'],['SELECT TOP 5 * FROM alumno;',false,'TOP es de SQL Server, no de MySQL.'],['SELECT * FROM alumno WHERE id <= 5;',false,'Depende de los ids, no de las filas.'],['SELECT 5 * FROM alumno;',false,'No es sintaxis válida.']],truco:'MySQL = LIMIT.'},
{id:'dm12',topic:'dml',type:'choice',title:'BETWEEN',q:'Alumnos nacidos en los 90 (Boletín extra, ej. 11):',opts:[["WHERE fecha_nacimiento BETWEEN '1990-01-01' AND '1999-12-31'",true,'BETWEEN incluye los extremos.'],["WHERE fecha_nacimiento > 1990 AND < 1999",false,'Sintaxis incorrecta.'],["WHERE fecha_nacimiento LIKE '199'",false,'Sin % solo vale el texto exacto "199".'],["WHERE YEAR(fecha_nacimiento) IN (1990, 1999)",false,'Solo esos dos años.']],truco:'BETWEEN a AND b incluye a y b. También: YEAR(fecha) BETWEEN 1990 AND 1999.'},
{id:'dm13',topic:'dml',type:'match',title:'Agregados del Boletín 1',prompt:'Une cada ejercicio con su función.',pairs:[['Edad máxima de los ciclistas','MAX(edad)','El mayor valor.'],['Cuántos ciclistas hay','COUNT(*)','Cuenta filas.'],['Edad media','AVG(edad)','Media.'],['Distancia total de las etapas','SUM(km)','Suma.'],['Etapa más corta','MIN(km)','El menor valor.']],truco:'MAX, MIN, AVG, SUM, COUNT.'},
{id:'dm14',topic:'dml',type:'order',title:'Orden de las cláusulas',q:'Ordena las cláusulas como se ESCRIBEN.',steps:['SELECT','FROM','WHERE','GROUP BY','HAVING','ORDER BY','LIMIT'],why:'Es el orden obligatorio de escritura.',truco:'"Siempre Faltan Whiskys Grandes Hasta Otra Luna".'},
{id:'dm15',topic:'dml',type:'short',title:'Escribe: GROUP BY',q:'Boletín 1, ej. 11: escribe la consulta que obtiene cuántos ciclistas hay en cada equipo (tabla ciclista, columna nomeq).',groups:[['select'],['nomeq'],['count'],['group by nomeq','group by  nomeq']],model:'SELECT nomeq, COUNT(*) AS num_ciclistas FROM ciclista GROUP BY nomeq;',why:'Necesitas COUNT y agrupar por equipo.',truco:'"De cada X" → GROUP BY X.'},
{id:'dm16',topic:'dml',type:'short',title:'Escribe: ¿por qué está mal?',q:'¿Por qué está mal esta consulta para "reparaciones sin fecha de salida"?',code:'SELECT * FROM reparacion WHERE fecha_salida = NULL;',groups:[['is null'],['nunca','siempre falso','falso','no devuelve','ninguna','no se compara','no es igual']],model:'Porque "= NULL" nunca es verdadero (NULL no es igual a nada) y la consulta no devuelve ninguna fila. Hay que usar WHERE fecha_salida IS NULL.',why:'Hay que decir la forma correcta y por qué falla la otra.',truco:'NULL no es igual a nada, ni a NULL.'},
{id:'dm17',topic:'dml',type:'short',title:'Escribe: existencialidad',q:'¿Por qué falla? (MECANICO solo tiene los id 5 y 6)',code:"INSERT INTO reparacion (numero_orden, fecha_entrada, vehiculo_id, mecanico_id)\nVALUES ('R-006', '2026-11-10', 10, 7);",groups:[['7'],['no existe','inexistente','no esta'],['fk','foreign','clave ajena','integridad','referenc']],model:'El mecánico 7 no existe en MECANICO. mecanico_id es una clave ajena y su valor tiene que existir en la tabla padre: se viola la integridad referencial.',why:'Valor concreto + no existe + es una FK.',truco:'Di el valor, di que no existe y di que es FK.'},
{id:'dm18',topic:'dml',type:'multi',title:'Antes de un INSERT',q:'Marca lo que puede hacer fallar un INSERT.',opts:[['Que la PK ya exista',true,'Duplicado.'],['Que la FK no exista en la tabla padre',true,'Integridad referencial.'],['Dejar NULL una columna NOT NULL',true,'Violación de NOT NULL.'],['Repetir un valor UNIQUE',true,'Duplicado de clave alternativa.'],['No poner WHERE',false,'INSERT no lleva WHERE.']],truco:'¿Ya existe? ¿Existe el padre? ¿Falta algo obligatorio? ¿Se repite algo único?'},

// ======================= NORMALIZACIÓN =======================
{id:'nf1',topic:'norm',type:'match',title:'Anomalías',prompt:'Une cada anomalía con su ejemplo.',pairs:[['Inserción','No puedes dar de alta un producto sin inventarte un pedido','Falta "algo" para poder insertar.'],['Actualización','Cambias el nombre del cliente en una fila y no en otra','Datos repetidos que dejan de coincidir.'],['Borrado','Al borrar el único pedido pierdes los datos del cliente','Te llevas información que no querías.']],truco:'I-A-B: Insertar, Actualizar, Borrar.'},
{id:'nf2',topic:'norm',type:'choice',title:'1FN',q:'X = a0 + a1 + {x + y + z} (Boletín normalización, ej. 1). ¿Qué rompe la 1FN?',opts:[['El grupo repetitivo {x + y + z}',true,'Las llaves indican repetición: hay que sacarlo a otra tabla con a0.'],['a1',false,'Es un atributo simple.'],['Que a0 sea la clave',false,'Eso es normal.'],['Nada',false,'Las llaves la rompen.']],truco:'{ } = se repite = fuera de la 1FN.'},
{id:'nf3',topic:'norm',type:'choice',title:'2FN',q:'LINEA(pedido_id, producto_id, unidades, fecha_pedido), CP(pedido_id, producto_id), pedido_id → fecha_pedido. ¿Qué forma normal incumple?',opts:[['2FN: fecha_pedido depende de solo una parte de la clave',true,'Dependencia parcial → se lleva a PEDIDO.'],['1FN',false,'Todos los valores son atómicos.'],['3FN solamente',false,'Falla antes, en 2FN.'],['Ninguna',false,'Hay dependencia parcial.']],truco:'2FN = "toda la clave".'},
{id:'nf4',topic:'norm',type:'choice',title:'3FN',q:'PEDIDO(id, fecha, cliente_id, cliente_nombre). id → cliente_id y cliente_id → cliente_nombre. ¿Qué pasa?',opts:[['Dependencia transitiva: incumple 3FN; cliente_nombre va a CLIENTE',true,'Un no primo depende de otro no primo.'],['Incumple 1FN',false,'Todo es atómico.'],['Incumple 2FN',false,'La CP es simple: no hay parciales.'],['Está en FNBC',false,'cliente_id no es superclave de PEDIDO.']],truco:'3FN = "nada más que la clave".'},
{id:'nf5',topic:'norm',type:'choice',title:'CP simple y 2FN',q:'Una tabla está en 1FN y su CP es de una sola columna. ¿Está en 2FN?',opts:[['Sí, siempre',true,'Sin CP compuesta no puede haber dependencias parciales.'],['No, nunca',false,'Al revés.'],['Depende de los tipos',false,'No depende.'],['Solo si no hay FK',false,'No tiene que ver.']],truco:'Sin clave compuesta no hay "media clave".'},
{id:'nf6',topic:'norm',type:'choice',title:'FNBC',q:'¿Qué exige la FNBC?',opts:[['Que en toda DF no trivial X → Y, X sea superclave',true,'Todo determinante es clave.'],['Que no haya NULL',false,'No es eso.'],['Que todas las CP sean simples',false,'No.'],['Que no haya FK',false,'No.']],truco:'FNBC = "todo el que determina, es clave".'},
{id:'nf7',topic:'norm',type:'choice',title:'Sin pérdida',q:'Partes R en R1 y R2. ¿Cuándo es una descomposición sin pérdida?',opts:[['Cuando R1 ∩ R2 es superclave de R1 o de R2',true,'Así el JOIN no se inventa filas.'],['Siempre',false,'Si lo común no es clave, aparecen filas falsas.'],['Cuando R1 y R2 tienen las mismas columnas',false,'No.'],['Cuando no hay FK',false,'No.']],truco:'Lo común tiene que ser clave de alguna.'},
{id:'nf8',topic:'norm',type:'choice',title:'Precio en la línea',q:'¿Por qué precio_ud en LINEA no es redundancia aunque PRODUCTO tenga pvp?',opts:[['Porque guarda el precio de ese momento (histórico)',true,'El pvp puede cambiar; lo pagado no.'],['Porque está prohibido usar el de producto',false,'No.'],['Sí es redundancia y hay que quitarlo',false,'Perderías el histórico.'],['Porque es derivado',false,'No se puede calcular si el pvp cambia.']],truco:'Precio de la línea = lo que pagó. pvp = lo que cuesta hoy.'},
{id:'nf9',topic:'norm',type:'order',title:'Síntesis a 3FN',q:'Ordena el algoritmo de síntesis a 3FN.',steps:['Obtener la cobertura mínima de las DF','Crear una tabla por cada determinante con lo que determina','Si ninguna tabla tiene una clave candidata, añadir una','Quitar las tablas contenidas en otras'],why:'Garantiza preservar las DF y no perder información.',truco:'Limpiar DF → tablas → asegurar clave → quitar sobrantes.'},
{id:'nf10',topic:'norm',type:'match',title:'Notación DeMarco',prompt:'Une cada símbolo con su significado.',pairs:[['{ }','Repetición','Grupo repetitivo.'],['[ ]','Opcional','Puede no estar.'],['( )','Composición','Partes de un atributo.'],['Subrayado','Clave primaria','Identifica.']],truco:'Llaves = se repite. Corchetes = opcional.'},
{id:'nf11',topic:'norm',type:'short',title:'Escribe: 3FN',q:'Explica qué es una dependencia transitiva y qué forma normal la prohíbe.',groups:[['3fn','tercera'],['no primo','no clave','intermedi','otro atributo','a traves']],model:'Es cuando un atributo no clave depende de la clave a través de otro atributo no clave (id → cliente_id → cliente_nombre). La prohíbe la 3FN.',why:'Definición + 3FN.',truco:'Transitiva = depende "de rebote".'},

// ======================= ALMACENAMIENTO =======================
{id:'al1',topic:'alm',type:'choice',title:'Dato o información',q:'¿Cuál es INFORMACIÓN y no un simple dato?',opts:[['"El 15/06/2024 en Valencia hubo 25 ºC"',true,'Tiene contexto: qué, dónde y cuándo.'],['"25"',false,'Valor aislado.'],['"2024-12-25"',false,'Fecha suelta.'],['"EUR 1500"',false,'Sin contexto.']],truco:'Información = dato + contexto.'},
{id:'al2',topic:'alm',type:'choice',title:'Ficheros',q:'María cambia su email y hay que tocarlo en 3 ficheros. Si se olvida uno, ¿qué problema aparece?',opts:[['Inconsistencia (por culpa de la redundancia)',true,'El mismo dato repetido deja de coincidir.'],['Falta de concurrencia',false,'Eso es editar a la vez.'],['Escasa seguridad',false,'No es de permisos.'],['Ninguno',false,'Hay datos contradictorios.']],truco:'Redundancia es la madre; inconsistencia, la hija.'},
{id:'al3',topic:'alm',type:'match',title:'ACID',prompt:'Une cada propiedad con su ejemplo de la transferencia.',pairs:[['Atomicidad','Si falla el cargo, tampoco se hace el abono','Todo o nada.'],['Consistencia','La suma de saldos cuadra antes y después','De válido a válido.'],['Aislamiento','Dos usuarios no compran a la vez el último artículo','No se pisan.'],['Durabilidad','El pago confirmado no se pierde si se cae el sistema','Persiste.']],truco:'A-C-I-D: todo o nada, cuadra, no se pisan, no se pierde.'},
{id:'al4',topic:'alm',type:'match',title:'Tipos de NoSQL',prompt:'Une cada tipo con su ejemplo y uso.',pairs:[['Documental','MongoDB: catálogos y webs','JSON/BSON.'],['Clave-valor','Redis: cachés, sesiones, carritos','Muy rápido.'],['Columnar','Cassandra: big data y series temporales','Familias de columnas.'],['Grafos','Neo4j: redes sociales y recomendaciones','Nodos y relaciones.']],truco:'Mongo documentos, Redis rápido, Cassandra columnas, Neo4j nodos.'},
{id:'al5',topic:'alm',type:'choice',title:'CAP',q:'Según el teorema CAP, un sistema distribuido puede garantizar a la vez…',opts:[['Solo 2 de las 3: consistencia, disponibilidad y tolerancia a particiones',true,'Eric Brewer, 2000.'],['Las 3 si es relacional',false,'No.'],['Solo 1',false,'Dos.'],['Las 3 con suficientes servidores',false,'Es un límite teórico.']],truco:'Bueno, bonito y barato: elige dos.'},
{id:'al6',topic:'alm',type:'choice',title:'Cassandra',q:'Cassandra siempre responde aunque los nodos tengan temporalmente datos distintos. ¿Qué tipo CAP es?',opts:[['AP (consistencia eventual)',true,'Disponibilidad + tolerancia a particiones.'],['CP',false,'CP sacrifica disponibilidad.'],['CA',false,'CA no tolera particiones.'],['ACID',false,'Eso no es una categoría CAP.']],truco:'Siempre responde = A de Available.'},
{id:'al7',topic:'alm',type:'choice',title:'Catálogo',q:'¿Qué componente del SGBD guarda la metainformación (qué tablas, vistas, índices y permisos hay)?',opts:[['El catálogo o diccionario de datos',true,'El "mapa" de la base de datos.'],['El motor de almacenamiento',false,'Guarda los datos en disco.'],['El procesador de consultas',false,'Traduce y optimiza SQL.'],['El gestor de copias',false,'Hace backups.']],truco:'Catálogo = datos sobre los datos.'},
{id:'al8',topic:'alm',type:'order',title:'Historia de los SGBD',q:'Ordena los tipos de SGBD según aparecieron.',steps:['Jerárquicos (árbol, IBM IMS)','En red (grafo, IDMS)','Relacionales (tablas, años 80)','NoSQL (finales de los 2000)'],why:'Del árbol a la red, a las tablas, y después NoSQL para la escala de Google o Amazon.',truco:'Árbol → Red → Tabla → NoSQL.'},
{id:'al9',topic:'alm',type:'choice',title:'Escalar',q:'¿Cómo escala típicamente una base de datos NoSQL?',opts:[['En horizontal: añadiendo más servidores',true,'Reparte datos entre muchas máquinas.'],['En vertical: un servidor más potente',false,'Eso es lo típico del relacional.'],['No escala',false,'Escala mucho.'],['Solo con más RAM',false,'Eso es vertical.']],truco:'Horizontal = más máquinas en fila.'},
{id:'al10',topic:'alm',type:'short',title:'Escribe: ficheros',q:'Nombra tres problemas de guardar la información en ficheros.',groups:[['redundan','duplic'],['inconsisten','integridad','seguridad','concurren','acceso','mantenimiento','copias']],model:'Redundancia, inconsistencia, acceso difícil, escasa seguridad, falta de integridad, mantenimiento costoso, concurrencia limitada y falta de copias automáticas.',why:'La redundancia y al menos otro más.',truco:'Empieza por la redundancia: de ella salen casi todos.'}
];
